from lib import *
S = SS('t1')
steps = [
    step("先看没拆开的情形:订单、库存、余额三张表在同一个 MySQL 实例里,下单放进一个事务。用户余额只有 50、商品 80 元,第三步 update wallet 触发 CHECK 约束报错 3819。事务回滚后订单 0 条、库存 10、余额 50,三张表全部回到初始值。这就是本地事务给的保证:同一个实例里的几个修改,要么全成,要么全不成。", t=tl(S(1)), mark=lidx(S(1), '失败:(3819'), done=lidx(S(1), '回滚后(单库)'), b=bars([['订单数', 0, '0'], ['库存', 10, '10(没变)'], ['余额', 50, '50(没变)']], 50, done=[0, 1, 2]), kv=KV([['事务范围', '一个实例,一个事务'], ['第三步失败', '前两步一起回滚'], ['结果', '三张表回到初始值']], ['结果'])),
    step("把同样的三张表拆到三个独立的 MySQL 实例(订单库、库存库、钱包库),同样的三步,每个实例只能提交自己的事务。订单库 COMMIT 成功、库存库 COMMIT 成功,到钱包库扣款同样报 3819,钱包库只能回滚自己这一步。最后订单库有 1 条订单、库存库 sku-1 从 10 变成 9、钱包库余额还是 50——订单存在、库存扣了、钱没收。已经提交的两步没有任何东西能替它们回滚。", t=tl(S(2)), mark=lidx(S(2), '失败:(3819'), done=lidx(S(2), '结果:订单库 1 条'), b=bars([['订单库 订单数', 1, '1'], ['库存库 库存', 9, '9(原来 10)'], ['钱包库 余额', 50, '50(没扣)']], 50, mark=[0, 1], done=[2]), kv=KV([['订单库', '已提交'], ['库存库', '已提交'], ['钱包库', '失败,只回滚自己'], ['全局', '没有人能撤销前两步']], ['全局'])),
    step("失败不一定来自业务:调用方进程在两次提交之间被 kill -9 也一样。订单库 → 库存库 → 钱包库的顺序,在四个位置各杀一次:第 1 次提交之前杀,三个库都没变,一致;订单库提交之后杀,订单 1 条、库存没扣、余额没扣,不一致;库存库提交之后杀,订单 1 条、库存扣了 1、余额没扣,不一致;三个都提交完之后再杀,订单 1、库存 1、余额 80,一致。四个位置里有两个把数据永远留在半截。", t=tl(S(3)), mark=lidx(S(3), '订单库提交之后', '库存库提交之后'), done=lidx(S(3), '第 1 次提交之前', '钱包库提交之后'), b=bars([['杀于订单库之后:订单数', 1, '1'], ['杀于订单库之后:库存扣了', 0, '0'], ['杀于库存库之后:库存扣了', 1, '1'], ['杀于库存库之后:余额扣了', 0, '0']], 1, mark=[0, 2]), kv=KV([['4 个位置', '2 个一致,2 个不一致'], ['半截状态', '进程死了就永远停在那里'], ['没有日志', '重启后不知道上次做到哪']], ['半截状态'])),
    step("把失败概率定量:每一步有 5% 的概率失败(用固定种子 7 的随机数,失败发生在该步执行之前),下 2000 单。三个实例各自提交时:成功 1715,第 1 步失败 108(什么都没留下),第 2 步失败 92(订单已存在),第 3 步失败 85(订单存在且库存已扣)。从数据库里数出来订单 1892 条、库存扣了 1800、余额折合 1715 单,三个数字对不上,不一致的单有 92 + 85 = 177 单(8.8%)。理论值 (1-p)p + (1-p)²p = 9.26%,期望 185 单、标准差约 13 单,实测差 8 单。同样的 2000 单放进一个实例的一个事务:三个数字都是 1715,不一致 0 单。", t=tl(S(4)), mark=lidx(S(4), '三个实例(每步各自提交)'), done=lidx(S(4), '一个实例(一个事务)', '三个数字完全相等'), b=bars([['订单数', 1892, '1892'], ['库存扣了', 1800, '1800'], ['余额折合单数', 1715, '1715'], ['不一致的单', 177, '177']], 2000, mark=[3], cur=[0, 1, 2]), kv=KV([['3 个实例', '177 单不一致(8.8%)'], ['理论值', '9.26%,期望 185 ± 13 单'], ['1 个实例', '0 单不一致']], ['3 个实例'])),
    step("本地事务的原子性靠的是这个实例自己的日志:事务没提交时 kill -9 mysqld。杀之前事务内能看到订单 2 和库存 5,这两个修改都没有 COMMIT;重启后只剩已提交的订单 1,库存回到 10,未提交的修改被回滚。错误日志里和恢复有关的行只有 “Starting XA crash recovery... / XA crash recovery finished.” 两行,InnoDB 自己回滚未提交事务的细节没有出现在默认级别的日志里。这套保证只覆盖一个实例:订单库的日志管不到库存库里发生了什么。", t=tl(S(5)), mark=lidx(S(5), 'kill -9 mysqld'), done=lidx(S(5), '重启后:订单 1 条'), b=bars([['重启后订单数', 1, '1(只剩已提交的)'], ['重启后库存', 10, '10(未提交的 -5 被撤销)']], 10, done=[0, 1]), kv=KV([['已提交', '重启后还在'], ['未提交', '重启后被回滚'], ['保证范围', '这一个实例自己的日志']], ['保证范围'])),
]
A = mkartt('t1', 1, '分布式事务,本地事务,MySQL,一致性,真实验证,动画演示',
    '实测本地事务的边界:同一个实例里余额不足会让订单和库存一起回滚;拆到三个 MySQL 实例后订单和库存已提交、钱没扣;kill -9 调用方进程会停在半截;5% 的单步失败率下 2000 单有 177 单(8.8%)不一致,同样的单放进一个事务是 0。',
    '一次下单要建订单、扣库存、扣余额。三张表在一个数据库里,一个事务就能搞定;表一旦分到三个库,会发生什么?这篇用三个真实的 MySQL 实例,把“跨库”的后果逐个跑出来:业务失败、进程被杀、按概率注入失败。',
    [('177 / 2000', '三个实例各自提交、每步 5% 失败率时,落在半截状态的订单数(8.8%)'), ('0', '同样 2000 单放进一个实例的一个事务,三张表对不上的单数'), ('2 / 4', 'kill -9 调用方进程的四个位置里,会把数据永远留在半截的有几个')],
    [('同一个实例里:一个事务管三张表', '<p>三张表在一个 MySQL 实例里,第三步触发 CHECK 约束报错,前两步一起回滚。本地事务的保证就是这样:同一个实例里的修改,要么全成,要么全不成。</p>'),
     ('拆成三个实例:各提交各的', '<p>每个实例只能提交或回滚自己的事务。第三步失败时,前两步已经提交,没有任何东西替它们回滚。三个库对同一单的看法不一样。</p>'),
     ('进程在间隙里被杀', '<p>不一定要有业务错误:调用方进程在两次提交之间被杀,数据也会永远停在半截。重启后没有任何地方记着“上次做到了哪一步”,下一篇起要讲的各种方案,都是在补这个记忆。</p>'),
     ('按概率算:半截状态有多常见', '<p>每一步 5% 的失败率看起来不高,三步串起来就是 9% 的订单留下半截状态。失败率越高、步骤越多、调用链越长,这个比例越大。</p>'),
     ('本地事务到底保证了什么', '<p>已提交的重启后还在,未提交的被回滚,靠的是实例自己的 redo/undo 日志。保证的范围只是这个实例。要让多个实例一起提交或一起回滚,就要有人在它们之上再做一层协调。</p>')],
    steps,
    [ENV_T + '。本篇用了四个独立的 MySQL 26.7.0 实例(订单库、库存库、钱包库,再加一个放着全部三张表的对照实例),调用方是 PyMySQL;kill -9 的是调用方子进程或 mysqld;5% 的失败是用固定种子 7 的随机数在每一步执行之前注入的,不是网络真实丢包',
     '没有验证:真实网络里的超时(请求可能已经被对端执行了但响应丢了);MySQL 以外的数据库;多个库在同一台机器上与分布在多台机器上的差别;调用方崩溃时 MySQL 连接的清理细节(这里是进程被杀后连接被服务端关闭)'],
    '本地事务的边界')
